#!/usr/bin/env python3
"""Patch build.gradle.kts generated by `flutter create` to sign release with private JKS."""
from pathlib import Path
import sys
p=Path('android/app/build.gradle.kts')
if not p.exists():
    sys.exit('当前构建流程要求 Flutter 生成的 Kotlin DSL build.gradle.kts。')
s=p.read_text('utf-8')
marker='    buildTypes {'
if s.count(marker)!=1:
    sys.exit('不能可靠定位 buildTypes，停止构建以防签名误配置。')
if 'create("release")' not in s:
    cfg="""    signingConfigs {
        create("release") {
            keyAlias = System.getenv("XY_KEY_ALIAS")
            keyPassword = System.getenv("XY_KEY_PASSWORD")
            storeFile = file("release-signing.jks")
            storePassword = System.getenv("XY_STORE_PASSWORD")
        }
    }
"""
    s=s.replace(marker,cfg+marker,1)
old='signingConfig = signingConfigs.getByName("debug")'
if old not in s:
    sys.exit('不能确定找到 Flutter 模板的 debug 发布签名，停止构建。')
s=s.replace(old,'signingConfig = signingConfigs.getByName("release")',1)
p.write_text(s,'utf-8')
print('APK Release 签名已切换为永久签名证书。')
